expected_fix.divide_fix:
def divide(self, a, b):
    if b == 0:
        raise ValueError("Cannot divide by zero")
    result = a / b
    self._record("divide", a, b, result)
    return result

expected_fix.modulo_fix:
def modulo(self, a, b):
    if b == 0:
        raise ValueError("Cannot divide by zero")
    result = a % b
    self._record("modulo", a, b, result)
    return result
